-- effectivePotentialCents / potential: marketFactorByTier[tier] × (1 + marketBonusPerLevel × level)
create or replace function public.company_market_factor(p_tier text, p_level integer)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_double('startups', array['marketFactorByTier', p_tier],
                                       case p_tier when 'small_business' then 4 when 'gmbh' then 15 when 'ag' then 40 else 1 end),
                  1)
       * (1 + public.config_double('startups', '{expansion,marketBonusPerLevel}', 0.5) * greatest(0, coalesce(p_level, 0)));
$$;
comment on function public.company_market_factor(text, integer) is
  'Market reach of a player company (ADR-083): marketFactorByTier[tier] × (1 + marketBonusPerLevel × expansion level).';

-- expansionCapacityFactor
create or replace function public.company_capacity_factor(p_level integer)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select 1 + public.config_double('startups', '{expansion,capacityBonusPerLevel}', 0.1) * greatest(0, coalesce(p_level, 0));
$$;

-- fixedCostCents(tier, level) per quarter
create or replace function public.company_fixed_cost_cents(p_tier text, p_level integer)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select round(coalesce((public.company_tier_cfg(p_tier) ->> 'fixedCostCentsPerQuarter')::bigint, 0)
               * (1 + public.config_double('startups', '{expansion,fixedCostPerLevel}', 0.25) * greatest(0, coalesce(p_level, 0))))::bigint;
$$;

-- maxEmployees(tier, level): places for players and AI workers
create or replace function public.company_max_employees(p_company uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((public.company_tier_cfg(pc.tier) ->> 'maxEmployees')::integer, 0)
       + public.config_double('startups', '{expansion,employeesPerLevel}', 10)::integer * pc.expansion_level
    from public.player_companies pc where pc.company_id = p_company;
$$;
comment on function public.company_max_employees(uuid) is
  'Places for players and AI workers (maxEmployees of the tier + employeesPerLevel × expansion level, ADR-083).';

-- canExpand
create or replace function public.company_can_expand(p_tier text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_jsonb('startups', '{expansion,fromTiers}'), '["gmbh", "ag"]'::jsonb) ? coalesce(p_tier, '');
$$;

-- expansionCostCents: price of the step from level n to n + 1
create or replace function public.company_expansion_cost_cents(p_level integer)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select round(public.config_double('startups', '{expansion,baseCostCents}', 10000000)
               * power(public.config_double('startups', '{expansion,costGrowth}', 1.8), greatest(0, coalesce(p_level, 0))))::bigint;
$$;

-- priceEffect: {price, demand, awareness}; premium below premiumMinQuality scares customers away
create or replace function public.company_price_effect(p_price_level text, p_quality double precision)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_lvl    text := case when p_price_level in ('budget', 'premium') then p_price_level else 'normal' end;
  v_price  double precision;
  v_demand double precision;
  v_aw     double precision;
begin
  v_price := public.config_double('startups', array['pricing', v_lvl, 'price'],
                                  case v_lvl when 'budget' then 0.8 when 'premium' then 1.3 else 1 end);
  v_demand := public.config_double('startups', array['pricing', v_lvl, 'demand'],
                                   case v_lvl when 'budget' then 1.35 when 'premium' then 0.75 else 1 end);
  v_aw := public.config_double('startups', array['pricing', v_lvl, 'awareness'],
                               case v_lvl when 'budget' then 1.5 when 'premium' then 0.7 else 1 end);
  if v_lvl = 'premium' and coalesce(p_quality, 0) < public.config_double('startups', '{pricing,premiumMinQuality}', 0.5) then
    v_demand := v_demand * public.config_double('startups', '{pricing,premiumLowQualityDemand}', 0.5);
  end if;
  return jsonb_build_object('price', v_price, 'demand', v_demand, 'awareness', v_aw);
end;
$$;

-- ---------------------------------------------------------------------------
-- C. One operating hour (closeStartupHour with price, contract work, expansion)
-- ---------------------------------------------------------------------------
create or replace function public.player_company_close_hour(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours   double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_start   timestamptz := date_trunc('hour', p_hour_start);
  v_end     timestamptz;
  v_qid     bigint;
  v_team    jsonb;
  v_price   jsonb;
  v_stage   integer;
  v_demand  double precision;
  v_cap     double precision;
  v_sold    double precision;
  v_ctr     double precision;
  v_own     bigint;
  v_crev    bigint;
  v_hhbal   bigint;
  v_rev     bigint;
  v_cogs    bigint;
  v_gross   bigint;
  v_aidue   bigint;
  v_aipaid  bigint;
  v_pdue    bigint := 0;
  v_ppaid   bigint := 0;
  v_due     bigint;
  v_factor  integer;
  v_fixed   bigint;
  v_mk      bigint;
  v_costs   bigint;
  v_paid    bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_profit  bigint;
  v_until   timestamptz;
  k         text;
  j         record;
begin
  if p_company is null or p_hour_start is null then
    return null;
  end if;
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_hours h where h.company_id = p_company and h.hour_start = v_start) then
    update public.player_companies set last_hour_at = greatest(last_hour_at, v_start + interval '1 hour')
     where company_id = p_company and last_hour_at < v_start + interval '1 hour';
    return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'skipped', 'already_closed');
  end if;
  v_end := v_start + interval '1 hour';
  select * into c from public.companies where id = p_company;
  select gq.id into v_qid from public.game_quarters gq where gq.starts_at <= v_start and gq.ends_at > v_start;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  k := 'pch:' || p_company::text || ':' || to_char(v_start at time zone 'UTC', 'YYYYMMDDHH24');

  -- sales of the hour with the quarter's awareness and quality; demand and capacity count in units at the
  -- normal price, the price strategy changes both price and demand (ADR-083)
  v_price := public.company_price_effect(pc.price_level, pc.quality);
  v_stage := least(greatest(coalesce((v_team ->> 'stage')::integer, 0), 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_demand := pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0 / v_hours
            * pc.awareness * (0.5 + 0.5 * pc.quality)
            * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random())
            * (v_price ->> 'demand')::double precision;
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000)
         * (1 + public.cfg_num(v_su, '{stages,capacityBonusPerStage}', 0.25) * v_stage)
         * public.company_capacity_factor(pc.expansion_level) / v_hours;
  v_sold := least(v_demand, v_cap);
  -- contract work: a share of the unused capacity at the normal price (ADR-083)
  v_ctr := case when pc.contract_work
                then greatest(0, v_cap - v_sold) * public.cfg_num(v_su, '{contractWork,shareOfFreeCapacity}', 0.25)
                else 0 end;
  v_own := round((v_sold * (v_price ->> 'price')::double precision)::numeric)::bigint;
  v_crev := round(v_ctr::numeric)::bigint;
  -- closed money system: the households pay at most what they have (own sales first)
  v_hhbal := greatest(0, coalesce((select a.balance_cents from public.ledger_accounts a where a.id = v_hh), 0));
  if v_own + v_crev > v_hhbal then
    v_own := least(v_own, v_hhbal);
    v_crev := least(v_crev, v_hhbal - v_own);
    v_sold := least(v_sold, v_own / greatest((v_price ->> 'price')::double precision, 0.0001));
    v_ctr := v_crev;
  end if;
  v_rev := v_own + v_crev;
  v_cogs := round((v_sold * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5)))::numeric)::bigint
          + round((v_ctr * (1 - public.cfg_num(v_su, '{contractWork,grossMargin}', 0.3)))::numeric)::bigint;
  v_gross := v_rev - v_cogs;

  -- wages due: AI workers and the hourly contract wages of the players (the founder draws no wage)
  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);
  for j in select pj.id, pj.salary_cents_per_hour, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    v_pdue := v_pdue + j.salary_cents_per_hour * public.job_payable_minutes(j.id, v_until) / 60;
  end loop;
  v_due := v_aidue + v_pdue;
  -- never more than the hour earned; everyone gets the same share (ADR-072)
  v_factor := case when v_due <= 0 then 10000 else least(10000, greatest(0, v_gross) * 10000 / v_due)::integer end;
  v_aipaid := v_aidue * v_factor / 10000;

  -- money: revenue (own sales and contract work) from the households, goods and AI wages back to them
  if v_rev > 0 then
    perform public.ledger_transfer(v_hh, v_acc, v_rev, 'company_revenue',
                                   'Umsatz ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':revenue', pc.founder_id);
  end if;
  if v_cogs + v_aipaid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_cogs + v_aipaid, 'company_costs', 'Wareneinsatz und KI-Kräfte',
                                   'company', p_company, k || ':goods', pc.founder_id);
  end if;
  -- players: the hour (up to the end of a notice) at contract wage x factor, with XP and branch minutes
  update public.player_companies set pay_factor_bps = v_factor where company_id = p_company;
  for j in select pj.id, pj.player_id, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    perform public.lock_player_accounts(j.player_id);
    v_ppaid := v_ppaid + public.accrue_job_salary(j.id, v_until);
  end loop;

  -- fixed costs (with the expansion level) and marketing from the cash; the rest becomes an open bill
  v_fixed := round((public.company_fixed_cost_cents(pc.tier, pc.expansion_level) / v_hours)::numeric)::bigint;
  v_mk := round((pc.marketing_cents_per_quarter / v_hours)::numeric)::bigint;
  v_costs := v_fixed + v_mk;
  select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_paid := least(v_costs, coalesce(v_cash, 0));
  if v_paid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_paid, 'company_costs', 'Fixkosten und Marketing',
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_paid;
  if v_unpaid = 0 and pc.unpaid_cents > 0 then
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, coalesce(v_cash, 0));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  v_profit := v_rev - v_cogs - v_ppaid - v_aipaid - v_fixed - v_mk;
  update public.player_companies
     set unpaid_cents = pc.unpaid_cents + v_unpaid - v_settle,
         distress = pc.unpaid_cents + v_unpaid - v_settle > 0,
         last_hour_at = greatest(pc.last_hour_at, v_end)
   where company_id = p_company;
  insert into public.player_company_hours (company_id, hour_start, game_quarter_id, demand_cents, capacity_cents, revenue_cents,
                                           contract_revenue_cents, cogs_cents, fixed_cents, marketing_cents, player_wages_due_cents,
                                           player_wages_paid_cents, ai_wages_due_cents, ai_wages_paid_cents, pay_factor_bps,
                                           paid_costs_cents, unpaid_added_cents, profit_cents)
  values (p_company, v_start, v_qid, round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint, v_rev,
          v_crev, v_cogs, v_fixed, v_mk, v_pdue, v_ppaid, v_aidue, v_aipaid, v_factor, v_paid, v_unpaid, v_profit);

  return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'quarter_id', v_qid, 'revenue_cents', v_rev,
                            'contract_revenue_cents', v_crev, 'profit_cents', v_profit, 'pay_factor_bps', v_factor,
                            'player_wages_paid_cents', v_ppaid, 'ai_wages_paid_cents', v_aipaid, 'unpaid_added_cents', v_unpaid);
end;
$$;
comment on function public.player_company_close_hour(uuid, timestamptz) is
  'Closes one operating hour of a player company (closeStartupHour, ADR-072/083); idempotent per (company, hour).';

-- ---------------------------------------------------------------------------
-- D. Quarter close as in M3i: marketing gain from the effective potential,
--    word of mouth x pricing.awareness (closeStartupQuarter, ADR-083)
-- ---------------------------------------------------------------------------
create or replace function public.player_company_close_quarter(p_company uuid, p_quarter_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  q         public.game_quarters;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_team    jsonb;
  v_target  double precision;
  v_quality double precision;
  v_mkq     bigint;
  v_half    double precision;
  v_gain    double precision := 0;
  v_aw      double precision;
  v_stage   integer;
  h         record;
  v_factor  integer;
  v_bwages  bigint;
  v_pool    bigint;
  v_weight  bigint;
  v_btotal  bigint := 0;
  v_bpaid   bigint := 0;
  v_b       bigint;
  v_cash    bigint;
  v_acc     uuid;
  v_xp      integer := 0;
  v_ai      integer;
  v_dq      integer;
  v_grace   integer := public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer;
  v_plp     jsonb := coalesce(public.config_jsonb('jobs', '{profitLinkedPay}'), '{}'::jsonb);
  v_prev    integer;
  k         text;
  b         record;
begin
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  select * into q from public.game_quarters where id = p_quarter_id;
  if pc.company_id is null or q.id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_reports r where r.company_id = p_company and r.game_quarter_id = p_quarter_id) then
    return jsonb_build_object('company_id', p_company, 'skipped', 'already_closed');
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  k := 'pcq:' || p_company::text || ':' || p_quarter_id::text;

  -- the quarter's operating hours (money was booked hourly)
  select count(*) as n,
         coalesce(sum(x.demand_cents), 0)::bigint as demand, coalesce(sum(x.capacity_cents), 0)::bigint as cap,
         coalesce(sum(x.revenue_cents), 0)::bigint as rev, coalesce(sum(x.cogs_cents), 0)::bigint as cogs,
         coalesce(sum(x.fixed_cents), 0)::bigint as fixed, coalesce(sum(x.marketing_cents), 0)::bigint as mk,
         coalesce(sum(x.player_wages_due_cents), 0)::bigint as pdue, coalesce(sum(x.player_wages_paid_cents), 0)::bigint as ppaid,
         coalesce(sum(x.ai_wages_due_cents), 0)::bigint as aidue, coalesce(sum(x.ai_wages_paid_cents), 0)::bigint as aipaid,
         coalesce(sum(x.paid_costs_cents), 0)::bigint as paidcosts, coalesce(sum(x.unpaid_added_cents), 0)::bigint as unpaid,
         coalesce(sum(x.profit_cents), 0)::bigint as profit
    into h
    from public.player_company_hours x where x.company_id = p_company and x.game_quarter_id = q.id;
  v_factor := case when h.pdue + h.aidue <= 0 then 10000
                   else least(10000, (h.ppaid + h.aipaid) * 10000 / (h.pdue + h.aidue))::integer end;

  -- quality towards what the team can do, awareness by word of mouth (x pricing.awareness) and marketing
  -- (half saturation from the effective potential, ADR-083) for the next quarter
  v_target := public.cfg_num(v_su, '{quality,base}', 0.25)
            + (1 - public.cfg_num(v_su, '{quality,base}', 0.25))
              * (greatest(0, (v_team ->> 'team_sector_score')::double precision)
                 / (greatest(0, (v_team ->> 'team_sector_score')::double precision) + public.cfg_num(v_su, '{quality,halfSaturationScore}', 20)));
  v_stage := least(greatest((v_team ->> 'stage')::integer, 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_target := least(1, v_target + public.cfg_num(v_su, '{stages,qualityBonusPerStage}', 0.05) * v_stage);
  -- AI workers do standard work (ADR-069)
  v_target := v_target * (1 - public.cfg_num(v_su, '{aiQualityPenalty}', 0.3)
              * pc.ai_workers::double precision
              / greatest(1, 1 + coalesce((v_team ->> 'employees')::integer, 0) + pc.ai_workers));
  v_quality := least(1, greatest(0, pc.quality + public.cfg_num(v_su, '{quality,adjustPerQuarter}', 0.35) * (v_target - pc.quality)));
  v_mkq := pc.marketing_cents_per_quarter;
  if v_mkq > 0 then
    v_half := greatest(public.cfg_num(v_su, '{awareness,marketingMinHalfSaturationCents}', 50000),
                       pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0
                       * public.cfg_num(v_su, '{awareness,marketingHalfSaturationShare}', 0.1));
    v_gain := public.cfg_num(v_su, '{awareness,marketingMaxGain}', 0.12) * v_mkq / (v_mkq + v_half);
  end if;
  v_aw := least(greatest(public.cfg_num(v_su, '{awareness,min}', 0.01),
                         coalesce((v_su #>> array['stages', 'awarenessCaps', v_stage::text])::double precision, 1)),
          greatest(public.cfg_num(v_su, '{awareness,min}', 0.01),
            pc.awareness
            + public.cfg_num(v_su, '{awareness,growthPerQuarter}', 0.3)
              * (public.company_price_effect(pc.price_level, pc.quality) ->> 'awareness')::double precision
              * pc.awareness * (1 - pc.awareness) * (0.5 + v_quality)
            + v_gain
            - public.cfg_num(v_su, '{awareness,decayPerQuarter}', 0.03) * pc.awareness));

  -- profit bonus (ADR-058): bonusShareOfProfit of the quarter's profit (after wages) by base-wage weight,
  -- at most maxBonusFactor x the base wages of the quarter
  select coalesce(sum(coalesce(sp.base_amount_cents, sp.minutes_paid::bigint * j.salary_cents_per_hour / 60)), 0) into v_bwages
    from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
   where j.company_id = p_company and sp.period_end > q.starts_at and sp.period_end <= q.ends_at;
  if to_regclass('pg_temp.nexa_bonus') is null then
    create temporary table nexa_bonus (job_id uuid, player_id uuid, bonus bigint) on commit drop;
  end if;
  delete from pg_temp.nexa_bonus;
  if h.profit > 0 then
    select coalesce(sum(x.w), 0) into v_weight
      from (select sum(coalesce(sp.base_amount_cents, sp.minutes_paid::bigint * j.salary_cents_per_hour / 60)) as w
              from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
             where j.company_id = p_company and j.status = 'active' and sp.period_end > q.starts_at and sp.period_end <= q.ends_at
             group by j.id) x;
    if v_weight > 0 then
      v_pool := floor(h.profit * public.cfg_num(v_plp, '{bonusShareOfProfit}', 0.2))::bigint;
      insert into pg_temp.nexa_bonus (job_id, player_id, bonus)
      select x.id, x.player_id, least(v_pool * x.w / v_weight, floor(x.w * public.cfg_num(v_plp, '{maxBonusFactor}', 1))::bigint)
        from (select j.id, j.player_id, sum(coalesce(sp.base_amount_cents, sp.minutes_paid::bigint * j.salary_cents_per_hour / 60)) as w
                from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
               where j.company_id = p_company and j.status = 'active' and sp.period_end > q.starts_at and sp.period_end <= q.ends_at
               group by j.id, j.player_id) x;
      delete from pg_temp.nexa_bonus where bonus <= 0;
      select coalesce(sum(bonus), 0) into v_btotal from pg_temp.nexa_bonus;
    end if;
  end if;
  if v_btotal > 0 then
    -- paid only from the cash that is there (scaled down proportionally)
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    for b in select * from pg_temp.nexa_bonus order by job_id loop
      v_b := case when v_cash >= v_btotal then b.bonus else b.bonus * v_cash / v_btotal end;
      if v_b > 0 then
        perform public.lock_player_accounts(b.player_id);
        perform public.ledger_transfer(v_acc, public.ledger_player_account(b.player_id, 'player_cash'), v_b, 'work_bonus',
                                       'Bonus ' || public.game_quarter_label(q.id), 'player_job', b.job_id,
                                       k || ':bonus:' || b.job_id::text, b.player_id);
        perform public.loan_withhold(b.player_id, v_b, k || ':bonus:' || b.job_id::text);
        insert into public.salary_payouts (player_job_id, player_id, pay_day, period_start, period_end, minutes_paid, amount_cents,
                                           bonus_cents, base_amount_cents)
        values (b.job_id, b.player_id, (q.ends_at at time zone 'Europe/Berlin')::date, q.starts_at, q.ends_at, 0, 0, v_b, 0);
        v_bpaid := v_bpaid + v_b;
      end if;
    end loop;
  end if;

  if h.profit > 0 then
    v_xp := public.grant_xp(pc.founder_id, 'company_quarter_profit',
                            public.config_double('progression', '{xpSources,profitableCompanyQuarter,xp}', 500)::integer,
                            'company_quarter:' || p_company::text || ':' || q.id::text, 'company', p_company);
  end if;

  -- distress (ADR-058): open bills at the close count one quarter; new bills this quarter let the AI workers go
  v_ai := case when pc.unpaid_cents > 0 and h.unpaid > 0 then 0 else pc.ai_workers end;
  v_dq := case when pc.unpaid_cents > 0 then pc.distress_quarters + 1 else 0 end;
  update public.player_companies
     set awareness = v_aw, quality = v_quality, quarters_active = quarters_active + 1, last_closed_quarter_id = q.id,
         distress = pc.unpaid_cents > 0, distress_quarters = v_dq, ai_workers = v_ai
   where company_id = p_company;

  select r.pay_factor_bps into v_prev
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  insert into public.player_company_reports (company_id, game_quarter_id, label, demand_cents, capacity_cents, revenue_cents,
                                             cogs_cents, fixed_cents, ai_worker_cents, marketing_cents, wages_cents,
                                             operating_profit_cents, utilization_bps, paid_costs_cents, unpaid_added_cents,
                                             awareness_bps, quality_bps, team_productivity_bps, team_sector_score,
                                             base_wages_cents, bonus_cents, pay_factor_bps)
  values (p_company, q.id, public.game_quarter_label(q.id), h.demand, h.cap, h.rev, h.cogs, h.fixed, h.aipaid, h.mk, h.ppaid,
          h.profit, round(case when h.cap > 0 then least(1, h.demand::double precision / h.cap) else 1 end * 10000)::integer,
          h.cogs + h.aipaid + h.paidcosts, h.unpaid, round(v_aw * 10000)::integer, round(v_quality * 10000)::integer,
          (v_team ->> 'team_productivity_bps')::integer, (v_team ->> 'team_sector_score')::integer,
          v_bwages, v_bpaid, v_factor);

  -- listed: fair value per share = company value / shares outstanding (ADR-067)
  if c.phase = 'listed' and c.security_id is not null then
    update public.security_sim_state
       set fair_value_e4 = greatest(1, public.company_value_cents(p_company) * 100 / greatest(c.shares_outstanding, 1))
     where security_id = c.security_id;
  end if;

  -- company chat
  perform public.company_system_message(p_company, 'Quartal ' || public.game_quarter_label(q.id) || ': Umsatz '
                                                   || public.format_eur(h.rev) || ', Gewinn ' || public.format_eur(h.profit) || '.');
  if v_bpaid > 0 then
    perform public.company_system_message(p_company, 'Bonus für das Team: ' || public.format_eur(v_bpaid) || '.');
  end if;
  if v_factor <> coalesce(v_prev, 10000) then
    perform public.company_system_message(p_company, 'Lohnfaktor im Quartal: ' || floor(v_factor / 100.0) || ' %.');
  end if;
  -- insolvency after graceQuarters closes with open bills (isInsolvent)
  if v_dq >= v_grace then
    perform public.company_dissolve(p_company, 'insolvent');
  elsif v_dq > 0 then
    perform public.company_system_message(p_company, 'Achtung: offene Rechnungen. Noch ' || (v_grace - v_dq)
                                                     || case when v_grace - v_dq = 1 then ' Quartal' else ' Quartale' end
                                                     || ' bis zur Insolvenz.');
  end if;

  return jsonb_build_object('company_id', p_company, 'quarter_id', q.id, 'hours', h.n, 'revenue_cents', h.rev,
                            'operating_profit_cents', h.profit, 'unpaid_added_cents', h.unpaid, 'xp', v_xp,
                            'base_wages_cents', v_bwages, 'bonus_cents', v_bpaid, 'pay_factor_bps', v_factor,
                            'distress_quarters', v_dq, 'dissolved', v_dq >= v_grace);
end;
$$;

-- ---------------------------------------------------------------------------
-- E. COMPANY: live details, contract revenue per hour, levers
-- ---------------------------------------------------------------------------
create or replace function public.company_live_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  v_day     timestamptz := ((public.game_now() at time zone 'Europe/Berlin')::date)::timestamp at time zone 'Europe/Berlin';
  v_qid     bigint := (public.current_game_quarter()).id;
  v_rev     bigint;
  v_profit  bigint;
  v_trev    bigint;
  v_tprofit bigint;
  v_qrev    bigint;
  v_qprofit bigint;
  h         public.player_company_hours;
begin
  select * into pc from public.player_companies where company_id = p_company;
  select * into h from public.player_company_hours x where x.company_id = p_company order by x.hour_start desc limit 1;
  v_rev := h.revenue_cents;
  v_profit := h.profit_cents;
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0) into v_trev, v_tprofit
    from public.player_company_hours x
   where x.company_id = p_company and x.hour_start >= v_day
     and x.hour_start < ((v_day at time zone 'Europe/Berlin') + interval '1 day') at time zone 'Europe/Berlin';
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0) into v_qrev, v_qprofit
    from public.player_company_hours x where x.company_id = p_company and x.game_quarter_id = v_qid;
  return jsonb_build_object(
    'last_hour_at', pc.last_hour_at,
    'revenue_per_hour_cents', coalesce(v_rev, 0),
    'profit_per_hour_cents', coalesce(v_profit, 0),
    'pay_factor_bps', pc.pay_factor_bps,
    'today_revenue_cents', v_trev,
    'today_profit_cents', v_tprofit,
    'quarter_revenue_cents', v_qrev,
    'quarter_profit_cents', v_qprofit,
    -- the last closed hour in detail (ADR-083: profit coach)
    'contract_revenue_per_hour_cents', coalesce(h.contract_revenue_cents, 0),
    'demand_per_hour_cents', coalesce(h.demand_cents, 0),
    'capacity_per_hour_cents', coalesce(h.capacity_cents, 0),
    'fixed_per_hour_cents', coalesce(h.fixed_cents, 0),
    'ai_wages_per_hour_cents', coalesce(h.ai_wages_paid_cents, 0),
    'marketing_per_hour_cents', coalesce(h.marketing_cents, 0));
end;
$$;
comment on function public.company_live_json(uuid) is
  'COMPANY.live: last closed hour (with its details, ADR-083), Berlin day and running quarter of a player company (ADR-072).';

create or replace function public.company_hours_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('hour_start', x.hour_start, 'revenue_cents', x.revenue_cents,
                                               'contract_revenue_cents', x.contract_revenue_cents,
                                               'profit_cents', x.profit_cents) order by x.hour_start), '[]'::jsonb)
    from (select h.hour_start, h.revenue_cents, h.contract_revenue_cents, h.profit_cents from public.player_company_hours h
           where h.company_id = p_company order by h.hour_start desc limit 24) x;
$$;
comment on function public.company_hours_json(uuid) is 'COMPANY.hours: the last 24 closed operating hours, oldest first.';

-- company_state as in M3j plus the levers of ADR-083 (appended: jsonb_build_object takes at most 100 arguments);
-- max_employees, capacity_cents and the estimate now include legal form and expansion
create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
  v_mf     double precision;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps,
           'bonus_cents', r.bonus_cents)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  v_cost := public.company_upgrade_cost(pc.tier);
  -- the estimate describes the market the company reaches (ADR-083)
  v_mf := public.company_market_factor(pc.tier, pc.expansion_level);
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'logo', public.company_logo(p_company),
    'logo_hidden', pc.logo_hidden,
    'founder_has_job', exists (select 1 from public.player_jobs x where x.player_id = pc.founder_id and x.status = 'active'),
    'full_time_from', public.config_double('startups', '{fullTimeFromEmployees}', 5)::integer,
    'training_from', public.config_double('startups', '{training,fromEmployees}', 5)::integer,
    'headcount', public.company_headcount(p_company),
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'distress_quarters', pc.distress_quarters,
    'grace_quarters', public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer,
    'pay_factor_bps', pc.pay_factor_bps,
    'product_key', public.company_product(p_company) ->> 'key',
    'stage', (v_team ->> 'stage')::integer,
    'stages', public.company_stages_json(p_company),
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents * v_mf
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents * v_mf
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 72000),
    'ai_wage_cents_per_hour', public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000),
    'ai_worker_skills', to_jsonb(pc.ai_worker_skills),
    'max_employees', public.company_max_employees(p_company),
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', round((v_team ->> 'capacity_cents')::bigint * public.company_capacity_factor(pc.expansion_level))::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', public.company_next_tier(pc.tier) is not null
                   and coalesce(v_level, 1) >= (public.company_tier_cfg(public.company_next_tier(pc.tier)) ->> 'minLevel')::integer,
    'listing', public.company_listing_json(p_company, pc.founder_id),
    'can_go_public', c.phase = 'private' and public.company_open_offer(p_company) is null
                     and coalesce(public.config_jsonb('startups', '{ipo,fromTiers}'), '["garage", "small_business", "gmbh"]'::jsonb) ? pc.tier
                     and coalesce(v_level, 1) >= public.config_double('startups', '{ipo,minLevel}', 6),
    'can_capital_increase', c.phase = 'listed' and public.company_open_offer(p_company) is null,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist,
    'live', public.company_live_json(p_company),
    'hours', public.company_hours_json(p_company))
    || jsonb_build_object(
         'banner', pc.banner,
         -- ADR-083: price strategy, contract work, expansion
         'price_level', pc.price_level,
         'contract_work', pc.contract_work,
         'expansion_level', pc.expansion_level,
         'can_expand', public.company_can_expand(pc.tier),
         'expansion_cost_cents', case when public.company_can_expand(pc.tier)
                                      then public.company_expansion_cost_cents(pc.expansion_level) end,
         'market_factor', round(v_mf::numeric, 4));
end;
$$;

-- ---------------------------------------------------------------------------
-- F. Founding as a GmbH, places with expansion levels
-- ---------------------------------------------------------------------------
-- found_company as in M3f, also as a GmbH (startups.gmbh), with the awareness head start of the tier (ADR-083)
create or replace function public.found_company(p_request_id uuid, p_name text, p_idea text, p_sector text, p_color text,
                                                p_tier text, p_product text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_idea   text := btrim(coalesce(p_idea, ''));
  v_reason text;
  v_tier   jsonb;
  v_level  integer;
  v_cost   bigint;
  v_cash   bigint;
  v_id     uuid := gen_random_uuid();
  v_acc    uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'found_company');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  if coalesce(p_tier, '') not in ('garage', 'small_business', 'gmbh')
     or not exists (select 1 from public.sectors s where s.key = p_sector)
     or public.config_jsonb('startups', array['capacityCentsPerProductivity', p_sector]) is null
     or coalesce(p_color, '') !~ '^#[0-9a-fA-F]{6}$'
     or char_length(v_idea) not between 1 and 120
     or (p_product is not null
         and not exists (select 1 from jsonb_array_elements(coalesce(public.config_jsonb('startups', array['products', p_sector]), '[]'::jsonb)) x
                          where x ->> 'key' = p_product)) then
    perform public.api_error('invalid_argument');
  end if;
  if public.text_has_profanity(v_idea) then
    perform public.api_error('name_profanity');
  end if;
  perform 1 from public.profiles p where p.id = v_player for update;
  if exists (select 1 from public.player_companies pc where pc.founder_id = v_player and pc.status = 'active') then
    perform public.api_error('company_exists');
  end if;
  if exists (select 1 from public.profiles p where p.id = v_player and p.founding_locked_until > now()) then
    perform public.api_error('founding_locked');
  end if;
  v_reason := public.name_violation(p_name, 'company');
  if v_reason is not null then
    perform public.api_error(v_reason);
  end if;
  v_tier := public.company_tier_cfg(p_tier);
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < (v_tier ->> 'minLevel')::integer then
    perform public.api_error('company_level_too_low');
  end if;
  v_cost := (v_tier ->> 'foundingCostCents')::bigint;
  perform public.lock_player_accounts(v_player);
  select a.balance_cents into v_cash from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash';
  if coalesce(v_cash, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;

  insert into public.companies (id, name, slug, description, sector_key, is_ai, legal_form, phase, founder_id, ceo_id,
                                brand_color, shares_outstanding, max_employees, founded_quarter_id, founded_at)
  values (v_id, p_name, trim(both '-' from lower(regexp_replace(p_name, '[^A-Za-z0-9]+', '-', 'g'))) || '-' || left(v_id::text, 8),
          v_idea, p_sector, false, case when p_tier = 'gmbh' then 'gmbh' else 'small_business' end::public.legal_form, 'private', v_player, v_player, lower(p_color), 1,
          (v_tier ->> 'maxEmployees')::integer, (public.current_game_quarter()).id, now());
  insert into public.ledger_accounts (kind, owner_company_id, label) values ('company_cash', v_id, 'Firmenkasse')
  returning id into v_acc;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), v_acc, v_cost, 'company_founding',
                                   'Gründung ' || p_name, 'company', v_id, 'found:' || v_id::text, v_player);
  end if;
  insert into public.player_companies (company_id, founder_id, idea, tier, potential_annual_cents, awareness, quality, request_id,
                                       product_key)
  values (v_id, v_player, v_idea, p_tier, public.startup_potential_from_uniform(1 - random()),
          -- founding bigger buys a head start (ADR-083, initialStartup(tier))
          least(1, greatest(0, public.config_double('startups', array['foundingAwareness', p_tier],
                                                    public.config_double('startups', '{awareness,initial}', 0.03)))),
          public.config_double('startups', '{quality,base}', 0.25),
          p_request_id,
          coalesce(p_product, public.config_jsonb('startups', array['products', p_sector]) -> 0 ->> 'key'));
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_id)));
end;
$$;

create or replace function public.sign_contract(p_request_id uuid, p_application_id uuid, p_signature text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  a        public.job_applications;
  p        public.job_postings;
  v_scores jsonb;
begin
  v_player := public.require_player();
  if p_request_id is null or p_signature is null or char_length(p_signature) < 1 or char_length(p_signature) > 8000 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'sign_contract');
  if v_replay is not null then
    return v_replay;
  end if;
  perform 1 from public.profiles pr where pr.id = v_player for update;
  select * into a from public.job_applications where id = p_application_id and player_id = v_player for update;
  if a.id is null then
    perform public.api_error('application_not_found');
  end if;
  if a.status <> 'offered' then
    perform public.api_error('application_not_offered');
  end if;
  if a.offer_expires_at <= now() then
    perform public.api_error('offer_expired');
  end if;
  if exists (select 1 from public.player_jobs j where j.player_id = v_player and j.status = 'active') then
    perform public.api_error('job_active_exists');
  end if;
  select * into p from public.job_postings where id = a.posting_id;
  -- founders: a job elsewhere only while the company has fewer than fullTimeFromEmployees people (ADR-066)
  if exists (select 1 from public.player_companies pc where pc.founder_id = v_player and pc.status = 'active'
                and (pc.company_id = p.company_id
                     or public.company_headcount(pc.company_id) >= public.config_double('startups', '{fullTimeFromEmployees}', 5))) then
    perform public.api_error('owns_company');
  end if;
  -- player companies: players with an active job there + AI workers <= max employees (tier and expansion, ADR-083)
  if exists (select 1 from public.player_companies pc where pc.company_id = p.company_id and pc.status = 'active'
                and (select count(*) from public.player_jobs j where j.company_id = pc.company_id and j.status = 'active')
                    + pc.ai_workers + 1 > public.company_max_employees(pc.company_id)) then
    perform public.api_error('employee_limit');
  end if;
  if p.slots is not null
     and (select count(*) from public.player_jobs j where j.posting_id = p.id and j.status = 'active') >= p.slots then
    perform public.api_error('job_not_found');
  end if;
  v_scores := public.player_branch_scores(v_player);
  insert into public.player_jobs (player_id, company_id, request_id, tier, title, title_key, required, salary_cents_per_hour,
                                  ceiling_cents_per_hour, raise_base_score, posting_id, application_id, signature,
                                  last_paid_at, started_at, paid_day, paid_minutes_today)
  values (v_player, p.company_id, p_request_id, p.tier, coalesce(p.title, p.title_key), p.title_key, p.required,
          a.offer_salary_cents_per_hour,
          case when p.is_ai then public.ai_salary_ceiling(p.salary_cents_per_hour, public.job_match_score(v_scores, p.required)) end,
          public.job_match_score(v_scores, p.required), p.id, a.id, p_signature,
          public.game_now(), public.game_now(), (public.game_now() at time zone 'Europe/Berlin')::date, 0);
  update public.job_applications set status = 'signed', signature = p_signature where id = a.id;
  update public.job_applications set status = 'closed'
   where player_id = v_player and id <> a.id and status in ('pending', 'offered');
  perform public.company_system_message(p.company_id,
    (select pr.nickname from public.profiles pr where pr.id = v_player) || ' ist jetzt im Team.');
  perform public.company_full_time_check(p.company_id);
  return public.request_complete(v_player, p_request_id, public.job_state(v_player));
end;
$$;

create or replace function public.set_ai_workers(p_request_id uuid, p_count integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_count is null or p_count < 0 or p_count > 1000 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_ai_workers');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if p_count + (select count(*) from public.player_jobs j where j.company_id = v_company and j.status = 'active')
     > public.company_max_employees(v_company) then
    perform public.api_error('employee_limit');
  end if;
  update public.player_companies set ai_workers = p_count where company_id = v_company;
  perform public.company_full_time_check(v_company);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- hire_ai_workers as in M3h; places include the expansion levels (ADR-083)
create or replace function public.hire_ai_workers(p_request_id uuid, p_count integer, p_skill text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_count is null or p_count < 1 or p_count > 1000
     or (p_skill is not null and p_count <> 1) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'hire_ai_workers');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if p_skill is not null then
    if not exists (select 1
                     from jsonb_array_elements(coalesce(public.company_product(v_company) -> 'stages', '[]'::jsonb)) st,
                          jsonb_array_elements_text(st) k
                    where k = p_skill) then
      perform public.api_error('invalid_argument');
    end if;
    if p_skill = any (pc.ai_worker_skills) then
      raise exception using errcode = 'NX062', message = 'skill_already_covered';
    end if;
  end if;
  if pc.ai_workers + p_count
     + (select count(*) from public.player_jobs j where j.company_id = v_company and j.status = 'active')
     > public.company_max_employees(v_company) then
    perform public.api_error('employee_limit');
  end if;
  update public.player_companies
     set ai_workers = ai_workers + p_count,
         ai_worker_skills = case when p_skill is null then ai_worker_skills else ai_worker_skills || p_skill end
   where company_id = v_company;
  perform public.company_full_time_check(v_company);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- ---------------------------------------------------------------------------
-- G. IPO from startups.ipo (garage included, level 6)
-- ---------------------------------------------------------------------------
-- go_public as in M3f; tiers and level only from startups.ipo (fallback: the values of ADR-083)
create or replace function public.go_public(p_request_id uuid, p_share_percent integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
  c         public.companies;
  v_ipo     jsonb := coalesce(public.config_jsonb('startups', '{ipo}'), '{}'::jsonb);
  v_total   bigint;
  v_price   bigint;
  v_level   integer;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_share_percent is null
     or p_share_percent < public.cfg_num(v_ipo, '{minSharePercent}', 10) or p_share_percent > public.cfg_num(v_ipo, '{maxSharePercent}', 49) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'go_public');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  select * into c from public.companies where id = v_company;
  if c.phase in ('ipo', 'listed') or public.company_open_offer(v_company) is not null then
    perform public.api_error('already_listed');
  end if;
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < public.cfg_num(v_ipo, '{minLevel}', 6) then
    perform public.api_error('company_level_too_low');
  end if;
  if not (coalesce(v_ipo -> 'fromTiers', '["garage", "small_business", "gmbh"]'::jsonb) ? pc.tier) then
    perform public.api_error('company_upgrade_unavailable');
  end if;
  v_total := public.cfg_num(v_ipo, '{sharesTotal}', 1000000)::bigint * 1000000;
  -- issuePriceCents: company value over all shares, at least minIssuePriceCents
  v_price := greatest(public.cfg_num(v_ipo, '{minIssuePriceCents}', 100)::bigint,
                      round(public.company_value_cents(v_company)::numeric / public.cfg_num(v_ipo, '{sharesTotal}', 1000000)::numeric)::bigint);
  insert into public.company_share_offers (company_id, kind, price_cents, shares_total_e6, shares_offered_e6, request_id, ends_at)
  values (v_company, 'ipo', v_price, v_total, v_total * p_share_percent / 100, p_request_id,
          now() + make_interval(secs => public.cfg_num(v_ipo, '{subscriptionHours}', 12) * 3600));
  update public.companies set phase = 'ipo' where id = v_company;
  perform public.company_system_message(v_company, 'Börsengang: ' || p_share_percent || ' % der Aktien zu '
                                                   || public.format_eur(v_price) || ' je Aktie, Zeichnung läuft.');
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- ---------------------------------------------------------------------------
-- H. RPCs: price strategy and contract work, expansion levels
-- ---------------------------------------------------------------------------
-- set_company_strategy: price level budget | normal | premium and contract work on/off (founder only)
create or replace function public.set_company_strategy(p_request_id uuid, p_price_level text, p_contract_work boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_contract_work is null or coalesce(p_price_level, '') not in ('budget', 'normal', 'premium') then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_company_strategy');
  if v_replay is not null then
    return v_replay;
  end if;
  update public.player_companies set price_level = p_price_level, contract_work = p_contract_work where company_id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.set_company_strategy(uuid, text, boolean) is
  'RPC (founder): price strategy budget | normal | premium and contract work on/off (ADR-083); error invalid_argument.';

-- expand_company: the next expansion level, paid from the company cash to the households (money sink back into the cycle)
create or replace function public.expand_company(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
  v_cost    bigint;
  v_free    bigint;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'expand_company');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if not public.company_can_expand(pc.tier) then
    perform public.api_error('company_upgrade_unavailable');
  end if;
  v_cost := public.company_expansion_cost_cents(pc.expansion_level);
  -- free cash: open bills come first (as company_withdraw)
  select a.balance_cents - pc.unpaid_cents into v_free
    from public.ledger_accounts a where a.owner_company_id = v_company and a.kind = 'company_cash' for update;
  if coalesce(v_free, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.company_cash_account(v_company), public.ledger_system_account('households'), v_cost,
                                   'company_costs', 'Ausbaustufe ' || (pc.expansion_level + 1), 'company', v_company,
                                   'expand:' || v_company::text || ':' || (pc.expansion_level + 1), v_player);
  end if;
  update public.player_companies set expansion_level = pc.expansion_level + 1 where company_id = v_company;
  update public.companies set max_employees = public.company_max_employees(v_company) where id = v_company;
  perform public.company_system_message(v_company, 'Ausbaustufe ' || (pc.expansion_level + 1) || ' für '
                                                   || public.format_eur(v_cost) || ': mehr Plätze, Kapazität und Markt.');
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.expand_company(uuid) is
  'RPC (founder): buys the next expansion level from the company cash (ADR-083); errors company_upgrade_unavailable, insufficient_funds.';

-- ---------------------------------------------------------------------------
-- I. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.company_market_factor(text, integer)', 'public.company_capacity_factor(integer)',
    'public.company_fixed_cost_cents(text, integer)', 'public.company_max_employees(uuid)', 'public.company_can_expand(text)',
    'public.company_expansion_cost_cents(integer)', 'public.company_price_effect(text, double precision)',
    'public.player_company_close_hour(uuid, timestamptz)', 'public.player_company_close_quarter(uuid, bigint)',
    'public.company_live_json(uuid)', 'public.company_hours_json(uuid)', 'public.company_state(uuid)',
    'public.found_company(uuid, text, text, text, text, text, text)', 'public.sign_contract(uuid, uuid, text)',
    'public.set_ai_workers(uuid, integer)', 'public.hire_ai_workers(uuid, integer, text)', 'public.go_public(uuid, integer)',
    'public.set_company_strategy(uuid, text, boolean)', 'public.expand_company(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.found_company(uuid, text, text, text, text, text, text)', 'public.sign_contract(uuid, uuid, text)',
    'public.set_ai_workers(uuid, integer)', 'public.hire_ai_workers(uuid, integer, text)', 'public.go_public(uuid, integer)',
    'public.set_company_strategy(uuid, text, boolean)', 'public.expand_company(uuid)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/migrations/20261124000200_m4c_friends.sql =====
-- =============================================================================
-- NEXA · M4c · 0200 · Friends (ADR-084)
-- =============================================================================
-- RPCs on the existing table public.friendships (one row per unordered pair):
--   get_friends()                                     -> FRIENDS
--   send_friend_request(request_id, nickname)         -> FRIENDS (a counter request accepts at once)
--   respond_friend_request(request_id, nickname, accept) -> FRIENDS (decline deletes the request)
--   remove_friend(request_id, nickname)               -> FRIENDS (friendship or own open request)
-- FRIENDS = {friends: [{nickname, level, since}], incoming: [{nickname, level, at}], outgoing: [{nickname, level, at}]}
-- Errors: player_not_found (unknown nickname), invalid_argument (self, no open request, bad input), rate_limited.
-- In-app notifications: friend_request (to the addressee), friend_accepted (to the requester).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Notification type for an accepted request
-- ---------------------------------------------------------------------------
insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('friend_accepted', 'social', 'Freundschaft angenommen', 'Jemand hat deine Freundschaftsanfrage angenommen.',
        'notif_friend', true, false, false, 275)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. Helpers
-- ---------------------------------------------------------------------------
-- FRIENDS from the point of view of p_player (deactivated players are left out)
create or replace function public.friends_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'level', p.level,
                                          'since', coalesce(f.responded_at, f.updated_at)) order by lower(p.nickname), p.id)
        from public.friendships f
        join public.profiles p on p.id = case when f.requester_id = p_player then f.addressee_id else f.requester_id end
       where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id) and not p.is_deactivated), '[]'::jsonb),
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.requester_id
       where f.status = 'pending' and f.addressee_id = p_player and not p.is_deactivated), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.addressee_id
       where f.status = 'pending' and f.requester_id = p_player and not p.is_deactivated), '[]'::jsonb));
$$;
comment on function public.friends_json(uuid) is
  'FRIENDS of a player (ADR-084): friends by nickname, incoming and outgoing open requests newest first.';

-- The other player of a friends RPC: active, found by nickname (case-insensitive, as get_player_card)
create or replace function public.friend_target(p_player uuid, p_nickname text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_nickname is null or char_length(btrim(p_nickname)) = 0 or char_length(p_nickname) > 64 then
    perform public.api_error('invalid_argument');
  end if;
  select x.id into v_id from public.profiles x where lower(x.nickname) = lower(btrim(p_nickname)) and not x.is_deactivated;
  if v_id is null then
    perform public.api_error('player_not_found');
  end if;
  if v_id = p_player then
    perform public.api_error('invalid_argument');
  end if;
  return v_id;
end;
$$;

-- In-app notification, unless the player switched the type off (missing preference: the type's default)
create or replace function public.friend_notify(p_player uuid, p_type text, p_title text, p_from_nickname text, p_dedupe text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.notification_types t where t.key = p_type) then
    return;
  end if;
  if not coalesce((select np.in_app_enabled from public.notification_preferences np
                    where np.player_id = p_player and np.type_key = p_type),
                  (select t.default_in_app from public.notification_types t where t.key = p_type), true) then
    return;
  end if;
  insert into public.notifications (player_id, type_key, title, body, payload, link, dedupe_key)
  values (p_player, p_type, p_title, p_from_nickname, jsonb_build_object('nickname', p_from_nickname),
          '/players/' || p_from_nickname, p_dedupe)
  on conflict (player_id, dedupe_key) do nothing;
end;
$$;

-- ---------------------------------------------------------------------------
-- C. RPCs
-- ---------------------------------------------------------------------------
create or replace function public.get_friends()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return public.friends_json(public.require_player());
end;
$$;
comment on function public.get_friends() is 'RPC: FRIENDS of the caller (ADR-084).';

-- A request; if the other player already asked me, this accepts it. Friends or an open own request: nothing happens.
-- A declined row may be requested again.
create or replace function public.send_friend_request(p_request_id uuid, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
  v_me     text;
  v_nick   text;
  f        public.friendships;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'send_friend_request');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  -- both players in a fixed order: one pair, one writer at a time
  perform 1 from public.profiles p where p.id in (v_player, v_other) order by p.id for update;
  select p.nickname into v_me from public.profiles p where p.id = v_player;
  select p.nickname into v_nick from public.profiles p where p.id = v_other;
  select * into f from public.friendships x
   where least(x.requester_id, x.addressee_id) = least(v_player, v_other)
     and greatest(x.requester_id, x.addressee_id) = greatest(v_player, v_other);
  if f.id is null then
    insert into public.friendships (requester_id, addressee_id, status, request_id)
    values (v_player, v_other, 'pending', p_request_id);
    perform public.friend_notify(v_other, 'friend_request', v_me || ' möchte mit dir befreundet sein.', v_me,
                                 'friend_request:' || p_request_id::text);
  elsif f.status = 'pending' and f.requester_id = v_other then
    -- counter request: friends at once
    update public.friendships set status = 'accepted', responded_at = now(), updated_at = now() where id = f.id;
    perform public.friend_notify(v_other, 'friend_accepted', v_me || ' hat deine Freundschaftsanfrage angenommen.', v_me,
                                 'friend_accepted:' || p_request_id::text);
  elsif f.status = 'declined' then
    update public.friendships
       set requester_id = v_player, addressee_id = v_other, status = 'pending', request_id = p_request_id,
           responded_at = null, created_at = now(), updated_at = now()
     where id = f.id;
    perform public.friend_notify(v_other, 'friend_request', v_me || ' möchte mit dir befreundet sein.', v_me,
                                 'friend_request:' || p_request_id::text);
  end if;
  -- accepted, own open request or blocked: nothing to do
  return public.request_complete(v_player, p_request_id, public.friends_json(v_player));
end;
$$;
comment on function public.send_friend_request(uuid, text) is
  'RPC: friend request to a player by nickname (ADR-084); a counter request accepts. Errors player_not_found, invalid_argument.';

-- Only the addressee of an open request; declining deletes it
create or replace function public.respond_friend_request(p_request_id uuid, p_nickname text, p_accept boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
  v_me     text;
  f        public.friendships;
begin
  v_player := public.require_player();
  if p_request_id is null or p_accept is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'respond_friend_request');
  if v_replay is not null then
    return v_replay;
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  perform 1 from public.profiles p where p.id in (v_player, v_other) order by p.id for update;
  select * into f from public.friendships x
   where x.requester_id = v_other and x.addressee_id = v_player and x.status = 'pending';
  if f.id is null then
    perform public.api_error('invalid_argument');
  end if;
  if p_accept then
    update public.friendships set status = 'accepted', responded_at = now(), updated_at = now() where id = f.id;
    select p.nickname into v_me from public.profiles p where p.id = v_player;
    perform public.friend_notify(v_other, 'friend_accepted', v_me || ' hat deine Freundschaftsanfrage angenommen.', v_me,
                                 'friend_accepted:' || p_request_id::text);
  else
    delete from public.friendships where id = f.id;
  end if;
  return public.request_complete(v_player, p_request_id, public.friends_json(v_player));
end;
$$;
comment on function public.respond_friend_request(uuid, text, boolean) is
  'RPC: accept or decline (deletes) an open friend request from a player (ADR-084). Errors player_not_found, invalid_argument.';

-- Ends a friendship or withdraws the own open request; anything else: nothing happens
create or replace function public.remove_friend(p_request_id uuid, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'remove_friend');
  if v_replay is not null then
    return v_replay;
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  perform 1 from public.profiles p where p.id in (v_player, v_other) order by p.id for update;
  delete from public.friendships x
   where least(x.requester_id, x.addressee_id) = least(v_player, v_other)
     and greatest(x.requester_id, x.addressee_id) = greatest(v_player, v_other)
     and (x.status = 'accepted' or (x.status = 'pending' and x.requester_id = v_player));
  return public.request_complete(v_player, p_request_id, public.friends_json(v_player));
end;
$$;
comment on function public.remove_friend(uuid, text) is
  'RPC: ends a friendship or withdraws the own open friend request (ADR-084). Error player_not_found.';

-- ---------------------------------------------------------------------------
-- D. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.friends_json(uuid)', 'public.friend_target(uuid, text)', 'public.friend_notify(uuid, text, text, text, text)',
    'public.get_friends()', 'public.send_friend_request(uuid, text)', 'public.respond_friend_request(uuid, text, boolean)',
    'public.remove_friend(uuid, text)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_friends()', 'public.send_friend_request(uuid, text)', 'public.respond_friend_request(uuid, text, boolean)',
    'public.remove_friend(uuid, text)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/migrations/20261125000100_m4d_player_tags.sql =====
-- =============================================================================
-- NEXA · M4d · 0100 · Player tags, lookalike-free names, player search (ADR-085)
-- =============================================================================
-- profiles.tag: permanent, globally unique 4-character tag (alphabet without 0/O/1/I), shown as "#K7Q2";
--   set by a column default on every insert, backfilled for existing players, kept on nickname change and reset.
-- name_key(nickname): lower case, umlauts/accents folded, leet digits mapped, underscores removed (no collapsing of
--   repeated letters). A new or changed nickname with the key of another player's nickname is name_taken; the
--   sign-up suffix loop avoids keys as well. Existing duplicates stay (non-unique index on the key).
-- player_by_handle(text): active player by nickname (case-insensitive), else by tag ("#K7Q2" / "k7q2").
-- New RPC:
--   search_players(query) -> {players: [{nickname, tag, level, avatar_key}]} (at most 8)
-- New field `tag` in: get_player_card, get_my_portfolio, FRIENDS entries (friends/incoming/outgoing),
--   get_rich_list entries (null for tycoons). get_player_card and the friends RPCs also accept a tag.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Player tag
-- ---------------------------------------------------------------------------
alter table public.profiles add column if not exists tag text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_tag_format' and conrelid = 'public.profiles'::regclass) then
    alter table public.profiles add constraint profiles_tag_format check (tag ~ '^[A-HJ-NP-Z2-9]{4}$');
  end if;
end;
$$;

-- A random free tag (32^4 = 1 048 576 tags); the unique index catches the rare race of two sign-ups.
create or replace function public.new_player_tag()
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  c_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_tag      text;
begin
  for i in 1..100 loop
    select string_agg(substr(c_alphabet, 1 + floor(random() * 32)::integer, 1), '') into v_tag from generate_series(1, 4);
    if not exists (select 1 from public.profiles p where p.tag = v_tag) then
      return v_tag;
    end if;
  end loop;
  raise exception 'could not generate a unique player tag' using errcode = 'NX007';
end;
$$;
comment on function public.new_player_tag() is 'Internal: a random unused player tag (ADR-085); default of profiles.tag.';

-- backfill row by row: every statement sees the tags handed out before it
do $$
declare
  r record;
begin
  for r in select p.id from public.profiles p where p.tag is null order by p.created_at, p.id loop
    update public.profiles set tag = public.new_player_tag() where id = r.id;
  end loop;
end;
$$;

alter table public.profiles alter column tag set default public.new_player_tag();
alter table public.profiles alter column tag set not null;
create unique index if not exists profiles_tag_uq on public.profiles (tag);
comment on column public.profiles.tag is 'Permanent public player tag, 4 characters from A-Z/2-9 without I and O, shown as #K7Q2 (ADR-085).';

-- ---------------------------------------------------------------------------
-- B. Name key (lookalikes) and lookup by nickname or tag
-- ---------------------------------------------------------------------------
-- "M1ra", "mi_ra", "MÍRA" -> "mira"; "Matthias" and "Mathias" stay different. Indexed below: changing
-- name_normalize or this function needs a reindex of profiles_name_key_idx.
create or replace function public.name_key(p_text text)
returns text
language sql
immutable
set search_path = ''
as $$
  select replace(public.name_normalize(p_text, true), '_', '');
$$;
comment on function public.name_key(text) is 'Internal: lookalike key of a nickname (ADR-085); two players must not share one.';

create index if not exists profiles_name_key_idx on public.profiles (public.name_key(nickname));

-- Active player by nickname (case-insensitive) or, if no nickname matches, by tag ("#K7Q2", "k7q2"); else NULL.
create or replace function public.player_by_handle(p_handle text)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select x.id from public.profiles x
      where lower(x.nickname) = lower(btrim(coalesce(p_handle, ''))) and not x.is_deactivated),
    (select x.id from public.profiles x
      where x.tag = upper(regexp_replace(btrim(coalesce(p_handle, '')), '^#', '')) and not x.is_deactivated));
$$;
comment on function public.player_by_handle(text) is 'Internal: active player by nickname, else by tag (ADR-085).';

-- ---------------------------------------------------------------------------
-- C. Names: lookalikes are taken (name_violation as in M2 plus the key check)
-- ---------------------------------------------------------------------------
create or replace function public.name_violation(p_name text, p_kind text default 'player', p_exclude uuid default null)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_names  jsonb := coalesce(public.config_jsonb('names'), '{}'::jsonb);
  v_min    integer;
  v_max    integer;
  v_full   text;
  v_tokens text[];
  v_raw    text[];
  v_cat    text;
begin
  if p_kind = 'company' then
    v_min := 3; v_max := 30;
  else
    v_min := public.cfg_num(v_names, '{minLength}', 3)::integer;
    v_max := public.cfg_num(v_names, '{maxLength}', 20)::integer;
  end if;
  if p_name is null or char_length(p_name) < v_min then
    return 'name_too_short';
  end if;
  if char_length(p_name) > v_max then
    return 'name_too_long';
  end if;
  if p_kind = 'company' then
    if p_name !~ '^[A-Za-zÄÖÜäöüßÀ-ÿ0-9 &.''-]+$' or p_name <> btrim(p_name) or p_name ~ '  ' then
      return 'name_invalid_chars';
    end if;
  elsif p_name !~ '^[A-Za-z0-9_]+$' then
    return 'name_invalid_chars';
  end if;

  v_full := public.name_letters(p_name);
  select coalesce(array_agg(regexp_replace(t, '(.)\1+', '\1', 'g')), '{}') into v_tokens
    from regexp_split_to_table(public.name_normalize(p_name, true), '[^a-z]+') t where t <> '';
  select coalesce(array_agg(m[1]), '{}') into v_raw
    from regexp_matches(public.name_normalize(p_name, false), '([a-z]+|[0-9]+)', 'g') m;
  if v_full = '' then
    return 'name_invalid_chars';
  end if;

  select t.category into v_cat
    from public.blocked_name_terms t
   where (t.match_mode = 'substring' and strpos(v_full, t.term) > 0)
      or (t.match_mode = 'token' and (t.term = v_full or t.term = any (v_tokens) or t.term = any (v_raw)))
      or (t.match_mode = 'code' and t.term = any (v_raw))
   order by (t.category = 'reserved'), t.term
   limit 1;
  if v_cat is not null then
    return case when v_cat = 'reserved' then 'name_reserved' else 'name_profanity' end;
  end if;

  -- dynamic reserved names: AI tycoons, AI companies (with and without legal form), tickers, index keys
  if exists (select 1 from public.rich_tycoons ty where public.name_letters(ty.name) = v_full
                or (char_length(public.name_letters(ty.name)) >= 5 and strpos(v_full, public.name_letters(ty.name)) > 0))
     or exists (select 1 from public.companies c
                 where c.is_ai and c.id is distinct from p_exclude
                   and (public.name_letters(c.name) = v_full
                        or (char_length(public.name_letters(regexp_replace(c.name, '\s+(AG|SE|GmbH|KG)$', '', 'i'))) >= 5
                            and strpos(v_full, public.name_letters(regexp_replace(c.name, '\s+(AG|SE|GmbH|KG)$', '', 'i'))) > 0)))
     or exists (select 1 from public.securities s
                 where lower(s.ticker) = any (v_raw) or lower(s.ticker) = lower(p_name)
                    or public.name_letters(s.ticker) = v_full)
     or exists (select 1 from public.indices i where lower(i.key) = any (v_raw) or public.name_letters(i.key) = v_full) then
    return 'name_reserved';
  end if;

  if p_kind = 'company' then
    if exists (select 1 from public.companies c where lower(c.name) = lower(p_name) and c.id is distinct from p_exclude) then
      return 'name_taken';
    end if;
  elsif exists (select 1 from public.profiles p
                 where (lower(p.nickname) = lower(p_name) or public.name_key(p.nickname) = public.name_key(p_name))
                   and p.id is distinct from p_exclude) then
    -- also lookalikes (ADR-085): same name key as another player's nickname
    return 'name_taken';
  end if;
  return null;
end;
$$;

-- ---------------------------------------------------------------------------
-- D. Sign-up (handle_new_user as in M2; the suffix loop also avoids lookalikes)
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_meta            jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_code            text  := nullif(upper(btrim(coalesce(v_meta ->> 'invite_code', ''))), '');
  v_invite_required boolean := public.config_boolean('auth', '{inviteRequired}', true);
  v_age_required    boolean := public.config_boolean('auth', '{ageConfirmationRequired}', true);
  v_age_confirmed   boolean := lower(coalesce(v_meta ->> 'age_confirmed', 'false')) in ('true', '1', 'yes');
  v_start_cents     bigint  := greatest(public.config_bigint('economy', '{startingCapitalCents}', 1000000), 0);
  v_vault_hours     double precision := greatest(0, least(
                        public.config_double('economy', '{vaultInitialHours}', 2),
                        public.config_double('economy', '{vaultCapHours}', 8)));
  v_max_len         integer := public.config_double('names', '{maxLength}', 20)::integer;
  v_invite          public.invite_codes;
  v_base            text;
  v_nickname        text;
  v_reason          text;
  v_attempt         integer := 0;
begin
  -- 18+ confirmation ---------------------------------------------------------
  if v_age_required and not v_age_confirmed then
    raise exception 'age confirmation (18+) is required' using errcode = 'NX007';
  end if;

  -- invite code ---------------------------------------------------------------
  if v_code is not null then
    select i.* into v_invite from public.invite_codes i where i.code = v_code for update;
    if not found
       or not v_invite.is_active
       or (v_invite.expires_at is not null and v_invite.expires_at <= now())
       or v_invite.used_count >= v_invite.max_uses then
      if v_invite_required then
        raise exception 'invite code is invalid, expired or used up' using errcode = 'NX005';
      end if;
      v_code := null;
    end if;
  elsif v_invite_required then
    raise exception 'an invite code is required' using errcode = 'NX005';
  end if;

  -- nickname: cleaned as before, forbidden names are rejected (the client
  -- pre-checks with check_nickname), taken names and lookalikes of taken names
  -- (same name key, ADR-085) get a numeric suffix; the tag comes from the column default
  v_base := left(regexp_replace(coalesce(v_meta ->> 'nickname', ''), '[^A-Za-z0-9_]', '', 'g'), v_max_len);
  if length(v_base) < 3 then
    v_base := 'Trader';
    v_nickname := v_base || (floor(random() * 90000) + 10000)::integer::text;
  else
    v_reason := public.name_violation(v_base, 'player');
    if v_reason in ('name_profanity', 'name_reserved') then
      perform public.api_error(v_reason);
    end if;
    v_nickname := v_base;
  end if;
  while exists (select 1 from public.profiles p
                 where lower(p.nickname) = lower(v_nickname) or public.name_key(p.nickname) = public.name_key(v_nickname)) loop
    v_attempt := v_attempt + 1;
    if v_attempt > 20 then
      raise exception 'could not generate a unique nickname' using errcode = 'NX007';
    end if;
    v_nickname := left(v_base, 15) || (floor(random() * 90000) + 10000)::integer::text;
  end loop;

  -- player rows ----------------------------------------------------------------
  insert into public.profiles (id, nickname) values (new.id, v_nickname);
  insert into public.player_private (player_id, age_confirmed_at)
  values (new.id, case when v_age_confirmed then now() end);
  insert into public.player_settings (player_id) values (new.id);
  insert into public.vaults (player_id, accrual_started_at)
  values (new.id, public.game_now() - make_interval(secs => v_vault_hours * 3600));
  insert into public.login_streaks (player_id) values (new.id);

  insert into public.player_unlocks (player_id, unlock_key)
  select new.id, u.key from public.unlocks u where u.level <= 1;

  insert into public.notification_preferences (player_id, type_key, in_app_enabled, push_enabled)
  select new.id, t.key, t.default_in_app, t.default_push from public.notification_types t;

  -- ledger: cash + reserve account, starting capital from the state -----------
  insert into public.ledger_accounts (kind, owner_player_id, label) values ('player_cash', new.id, 'Cash');
  insert into public.ledger_accounts (kind, owner_player_id, label)
  values ('player_reserve', new.id, 'Reserved (orders, subscriptions, margin)');

  if v_start_cents > 0 then
    perform public.state_payout(new.id, v_start_cents, 0, 'starting_capital', 'Starting capital',
                                'profile', new.id, 'starting_capital:' || new.id::text);
  end if;

  -- consume the invite ---------------------------------------------------------
  if v_code is not null then
    update public.invite_codes set used_count = used_count + 1 where code = v_code;
    insert into public.invite_code_redemptions (code, player_id) values (v_code, new.id);
  end if;

  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- E. Player card (as in M3d plus tag; also found by tag)
-- ---------------------------------------------------------------------------
create or replace function public.get_player_card(p_nickname text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  p      public.profiles;
  v_job  jsonb;
begin
  perform public.require_player();
  select * into p from public.profiles x where x.id = public.player_by_handle(p_nickname);
  if p.id is null then
    perform public.api_error('player_not_found');
  end if;
  select jsonb_build_object('company_name', c.name, 'title_key', j.title_key, 'title', case when j.title_key is null then j.title end,
                            'tier', j.tier, 'since', j.started_at)
    into v_job
    from public.player_jobs j join public.companies c on c.id = j.company_id
   where j.player_id = p.id and j.status = 'active';
  return jsonb_build_object(
    'nickname',        p.nickname,
    'tag',             p.tag,
    'avatar_key',      p.avatar_key,
    'level',           p.level,
    'rank',            public.player_rich_rank(p.id),
    'net_worth_cents', public.player_net_worth_cents(p.id),
    'streak_days',     public.player_streak_days(p.id),
    'skills_learned',  (select count(*) from public.player_skills s where s.player_id = p.id)::integer,
    'branch_scores',   public.player_branch_scores(p.id),
    'top_skills',      coalesce((select jsonb_agg(jsonb_build_object('key', x.skill_key, 'tier', x.tier) order by x.tier desc, x.learned_at)
                                   from (select s.skill_key, s.learned_at, (public.skill_node(s.skill_key) ->> 'tier')::integer as tier
                                           from public.player_skills s where s.player_id = p.id
                                          order by 3 desc nulls last, s.learned_at limit 3) x), '[]'::jsonb),
    'job',             v_job,
    'company',         (select jsonb_build_object('name', c.name, 'ticker', c.ticker)
                          from public.player_companies pc join public.companies c on c.id = pc.company_id
                         where pc.founder_id = p.id and pc.status = 'active'),
    'member_since',    p.created_at);
end;
$$;

-- ---------------------------------------------------------------------------
-- F. Portfolio (as in M3g plus the own tag)
-- ---------------------------------------------------------------------------
create or replace function public.get_my_portfolio()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player    uuid;
  v_cash      bigint;
  v_reserved  bigint;
  v_positions jsonb;
  v_value     bigint;
  v_bid_value bigint;
  v_orders    jsonb;
  v_trades    jsonb;
  v_prof      public.profiles;
  v_priv      public.player_private;
  v_level     jsonb;
  v_days      double precision := public.config_double('names', '{nicknameChangeDays}', 60);
  v_today     date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_streak    integer;
  ls          public.login_streaks;
begin
  v_player := public.require_player();
  select * into v_priv from public.player_private where player_id = v_player;
  select coalesce(sum(a.balance_cents) filter (where a.kind = 'player_cash'), 0),
         coalesce(sum(a.balance_cents) filter (where a.kind = 'player_reserve'), 0)
    into v_cash, v_reserved
    from public.ledger_accounts a where a.owner_player_id = v_player;

  select coalesce(jsonb_agg(jsonb_build_object(
           'ticker', x.ticker, 'name', x.name, 'kind', x.kind, 'quantity_e6', x.quantity_e6,
           'reserved_quantity_e6', x.reserved_quantity_e6, 'avg_price_e4', x.avg_entry_price_e4,
           'last_price_e4', x.last_price_e4, 'market_value_cents', x.mv, 'cost_basis_cents', x.cost_basis_cents,
           'unrealized_pnl_cents', x.mv - x.cost_basis_cents, 'realized_pnl_cents', x.realized_pnl_cents,
           'change_bps', x.change_bps, 'opened_at', x.opened_at)
           order by x.mv desc), '[]'::jsonb),
         coalesce(sum(x.mv), 0)::bigint,
         coalesce(sum(x.bv), 0)::bigint
    into v_positions, v_value, v_bid_value
    from (select s.ticker, s.name, s.kind, p.quantity_e6, p.reserved_quantity_e6, p.avg_entry_price_e4, p.cost_basis_cents,
                 p.realized_pnl_cents, p.opened_at, q.last_price_e4, q.change_bps,
                 public.value_cents(p.quantity_e6, q.last_price_e4) as mv,
                 public.value_cents(p.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)) as bv
            from public.positions p
            join public.securities s on s.id = p.security_id
            join public.security_quotes q on q.security_id = p.security_id
           where p.player_id = v_player and p.status = 'open' and p.quantity_e6 > 0) x;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', o.id, 'ticker', s.ticker, 'side', o.side, 'type', o.type, 'quantity_e6', o.quantity_e6,
           'filled_quantity_e6', o.filled_quantity_e6, 'limit_price_e4', o.limit_price_e4, 'status', o.status,
           'reserved_cents', o.reserved_cents, 'created_at', o.created_at)
           order by o.created_at desc), '[]'::jsonb)
    into v_orders
    from public.orders o join public.securities s on s.id = o.security_id
   where o.player_id = v_player and o.status in ('open', 'partially_filled');

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'ticker', t.ticker, 'side', t.side, 'quantity_e6', t.quantity_e6, 'price_e4', t.price_e4,
           'gross_cents', t.gross_cents, 'fee_cents', t.fee_cents, 'tax_cents', t.tax_cents,
           'realized_pnl_cents', t.realized_pnl_cents, 'xp_awarded', t.xp_awarded, 'executed_at', t.executed_at)
           order by t.executed_at desc), '[]'::jsonb)
    into v_trades
    from (select tr.*, s.ticker from public.trades tr join public.securities s on s.id = tr.security_id
           where tr.player_id = v_player and tr.executed_at > coalesce(v_priv.account_reset_at, '-infinity'::timestamptz)
           order by tr.executed_at desc limit 50) t;

  select * into v_prof from public.profiles where id = v_player;
  select * into ls from public.login_streaks where player_id = v_player;
  v_level := public.level_progress(v_prof.xp_total);
  v_streak := case when ls.last_login_day >= v_today - 1 then ls.current_streak
                   when ls.last_login_day = v_today - 2 and ls.freeze_tokens > 0 then ls.current_streak
                   else 0 end;

  return jsonb_build_object(
    'cash_cents',            v_cash,
    'reserved_cents',        v_reserved,
    'positions_value_cents', v_value,
    'total_cents',           v_cash + v_reserved + v_value,
    'net_worth_cents',       v_cash + v_reserved + v_bid_value,
    'loss_pot_cents',        coalesce(v_priv.tax_loss_pot_cents, 0),
    'vault',                 public.vault_status(v_player) - 'accrued_seconds' - 'base_rate_cents_per_hour',
    'positions',             v_positions,
    'open_orders',           v_orders,
    'recent_trades',         v_trades,
    'level',                 v_prof.level,
    'xp_total',              v_prof.xp_total,
    'xp_into_level',         (v_level ->> 'xp_into_level')::bigint,
    'xp_for_next',           (v_level ->> 'xp_for_next')::bigint,
    'tutorial_completed',    v_priv.tutorial_completed_at is not null,
    'nickname',              v_prof.nickname,
    'tag',                   v_prof.tag,
    'nickname_change_available_at',
                             case when v_prof.nickname_changed_at is null
                                    or v_prof.nickname_changed_at + make_interval(secs => v_days * 86400) <= now() then null
                                  else v_prof.nickname_changed_at + make_interval(secs => v_days * 86400) end,
    'missions_claimable',    (select count(*) from public.player_missions m
                               where m.player_id = v_player and m.status = 'completed'
                                 and (m.expires_at is null or m.expires_at > public.game_now()))::integer,
    'streak_days',           coalesce(v_streak, 0),
    'avatar_key',            coalesce(v_prof.avatar_key, 'rookie'),
    'skill_points_free',     coalesce((select sp.free_points from public.player_skill_points sp where sp.player_id = v_player), 0),
    'daily_reward_claimable', not exists (select 1 from public.daily_reward_claims c
                                           where c.player_id = v_player
                                             and c.claim_day = (public.game_now() at time zone 'Europe/Berlin')::date),
    'company_value_cents',   public.player_company_value_cents(v_player),
    'debt_cents',            public.player_debt_cents(v_player),
    'debt_withholding_bps',  public.config_double('startups', '{insolvency,loanWithholdingBps}', 5000)::integer,
    'founding_locked_until', case when v_prof.founding_locked_until > now() then v_prof.founding_locked_until end,
    'server_time',           public.game_now());
end;
$$;

-- ---------------------------------------------------------------------------
-- G. Rich list (as in M2b plus tag for players, null for tycoons)
-- ---------------------------------------------------------------------------
create or replace function public.get_rich_list(p_limit integer default 100, p_offset integer default 0, p_scope text default 'all')
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_limit   integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_offset  integer := greatest(coalesce(p_offset, 0), 0);
  v_scope   text := coalesce(p_scope, 'all');
  v_now     timestamptz := public.game_now();
  v_snap    timestamptz;
  v_out     jsonb;
begin
  v_player := public.require_player();
  if v_scope not in ('all', 'players') then
    perform public.api_error('invalid_argument');
  end if;
  -- the latest snapshot that is at least 24 h old
  select max(s.taken_at) into v_snap from public.rich_list_snapshots s where s.taken_at <= v_now - interval '24 hours';

  with lst as materialized (
    select e.entity_kind, e.entity_id, e.name, e.description, e.net_worth_cents,
           case when v_scope = 'players' then e.rank_players else e.rank_all end as rnk,
           case when s.net_worth_cents > 0 then round((e.net_worth_cents - s.net_worth_cents) * 10000.0 / s.net_worth_cents)::integer end as change_bps,
           case when s.entity_id is not null
                then (case when v_scope = 'players' then s.rank_players else s.rank_all end)
                   - (case when v_scope = 'players' then e.rank_players else e.rank_all end) end as rank_change
      from public.rich_list_entries() e
      left join public.rich_list_snapshots s on s.taken_at = v_snap and s.entity_kind = e.entity_kind and s.entity_id = e.entity_id
     where v_scope = 'all' or e.entity_kind = 'player'
  ), me as (
    select * from lst where entity_kind = 'player' and entity_id = v_player
  )
  select jsonb_build_object(
           'server_time', v_now,
           'total', (select count(*) from lst),
           'entries', (select coalesce(jsonb_agg(jsonb_build_object(
                          'rank', x.rnk, 'kind', x.entity_kind, 'id', x.entity_id, 'name', x.name, 'description', x.description,
                          'net_worth_cents', x.net_worth_cents, 'change_24h_bps', x.change_bps, 'rank_change_24h', x.rank_change,
                          'is_me', x.entity_kind = 'player' and x.entity_id = v_player,
                          'avatar_key', case when x.entity_kind = 'player'
                                             then (select pr.avatar_key from public.profiles pr where pr.id = x.entity_id)
                                             else public.tycoon_avatar_key(x.entity_id) end,
                          'tag', case when x.entity_kind = 'player'
                                      then (select pr.tag from public.profiles pr where pr.id = x.entity_id) end) order by x.rnk), '[]'::jsonb)
                         from (select * from lst order by rnk offset v_offset limit v_limit) x),
           'me', (select jsonb_build_object(
                           'rank', m.rnk, 'net_worth_cents', m.net_worth_cents,
                           'next', (select jsonb_build_object('rank', n.rnk, 'name', n.name, 'gap_cents', n.net_worth_cents - m.net_worth_cents)
                                      from lst n where n.rnk = m.rnk - 1))
                    from me m))
    into v_out;
  return v_out;
end;
$$;

-- ---------------------------------------------------------------------------
-- H. Friends: entries carry the tag, the other player is also found by tag
-- ---------------------------------------------------------------------------
create or replace function public.friends_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level,
                                          'since', coalesce(f.responded_at, f.updated_at)) order by lower(p.nickname), p.id)
        from public.friendships f
        join public.profiles p on p.id = case when f.requester_id = p_player then f.addressee_id else f.requester_id end
       where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id) and not p.is_deactivated), '[]'::jsonb),
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.requester_id
       where f.status = 'pending' and f.addressee_id = p_player and not p.is_deactivated), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.addressee_id
       where f.status = 'pending' and f.requester_id = p_player and not p.is_deactivated), '[]'::jsonb));
$$;
comment on function public.friends_json(uuid) is
  'FRIENDS of a player (ADR-084, tag ADR-085): friends by nickname, incoming and outgoing open requests newest first.';

-- The other player of a friends RPC: active, found by nickname (case-insensitive) or tag
create or replace function public.friend_target(p_player uuid, p_nickname text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_nickname is null or char_length(btrim(p_nickname)) = 0 or char_length(p_nickname) > 64 then
    perform public.api_error('invalid_argument');
  end if;
  v_id := public.player_by_handle(p_nickname);
  if v_id is null then
    perform public.api_error('player_not_found');
  end if;
  if v_id = p_player then
    perform public.api_error('invalid_argument');
  end if;
  return v_id;
end;
$$;

comment on function public.send_friend_request(uuid, text) is
  'RPC: friend request to a player by nickname or tag (ADR-084/085); a counter request accepts. Errors player_not_found, invalid_argument.';

-- ---------------------------------------------------------------------------
-- I. Player search (top search bar)
-- ---------------------------------------------------------------------------
-- Query trimmed, one leading '#' dropped; under 2 characters: no result. A valid tag puts its player first, then
-- nicknames (case-insensitive): exact, prefix, contains; each group by level desc, nickname. At most 8.
create or replace function public.search_players(p_query text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q    text := regexp_replace(btrim(coalesce(p_query, '')), '^#', '');
  v_like text;
  v_out  jsonb;
begin
  perform public.require_player();
  if char_length(v_q) < 2 or char_length(v_q) > 64 then
    return jsonb_build_object('players', '[]'::jsonb);
  end if;
  v_q := lower(v_q);
  -- user input is a LIKE literal: escape the wildcards and the escape character
  v_like := replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_');
  select coalesce(jsonb_agg(jsonb_build_object('nickname', x.nickname, 'tag', x.tag, 'level', x.level,
                                               'avatar_key', x.avatar_key)
                            order by x.grp, x.level desc, lower(x.nickname), x.nickname), '[]'::jsonb)
    into v_out
    from (select p.nickname, p.tag, p.level, p.avatar_key,
                 case when p.tag = upper(v_q) then 0
                      when lower(p.nickname) = v_q then 1
                      when lower(p.nickname) like v_like || '%' escape '\' then 2
                      else 3 end as grp
            from public.profiles p
           where not p.is_deactivated
             and (p.tag = upper(v_q) or lower(p.nickname) like '%' || v_like || '%' escape '\')
           order by grp, p.level desc, lower(p.nickname), p.nickname
           limit 8) x;
  return jsonb_build_object('players', v_out);
end;
$$;
comment on function public.search_players(text) is
  'RPC: player search by tag or nickname (exact, prefix, contains), at most 8 (ADR-085).';

-- ---------------------------------------------------------------------------
-- J. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.new_player_tag()', 'public.name_key(text)', 'public.player_by_handle(text)', 'public.search_players(text)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  grant execute on function public.search_players(text) to authenticated;
end;
$$;

-- ===== supabase/migrations/20261126000100_m4e_founder_payout.sql =====
-- =============================================================================
-- NEXA · M4e · 0100 · Automatic CEO payout (ADR-086)
-- =============================================================================
-- Mirrors src/lib/sim/startup.ts (isValidFounderPayout, founderPayoutCents):
--   player_companies.founder_payout_bps  share of the hourly profit, whole steps of
--                                        startups.founderPayout.stepBps from 0 to maxBps
--   payout = min(floor(profit × bps / 10 000), free cash)   only for a positive profit;
--            free cash = company cash − open bills (unpaid_cents) after the hour's own bookings
--            (the same rule as company_withdraw and expand_company)
-- player_company_close_hour books the payout after all other bookings of the hour exactly like
-- company_withdraw: company cash → founder's player_cash (kind 'transfer'), then loan_withhold on
-- the founder's income. profit_cents stays unchanged (a transfer, not a cost); the amount is stored
-- in player_company_hours.founder_payout_cents. Idempotent per (company, hour) like the rest of the hour.
-- New RPC set_founder_payout(request_id, bps) → {company}. COMPANY: founder_payout_bps,
-- live.founder_payout_per_hour_cents, live.today_founder_payout_cents, hours[].founder_payout_cents.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.player_companies add column if not exists founder_payout_bps integer not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_companies_founder_payout_bps_check'
                    and conrelid = 'public.player_companies'::regclass) then
    alter table public.player_companies add constraint player_companies_founder_payout_bps_check
      check (founder_payout_bps between 0 and 10000);
  end if;
end;
$$;
comment on column public.player_companies.founder_payout_bps is
  'Share of every profitable operating hour paid to the founder automatically (ADR-086), 0..10000 bps.';
grant select (founder_payout_bps) on public.player_companies to authenticated;

alter table public.player_company_hours add column if not exists founder_payout_cents bigint not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_company_hours_founder_payout_check'
                    and conrelid = 'public.player_company_hours'::regclass) then
    alter table public.player_company_hours add constraint player_company_hours_founder_payout_check
      check (founder_payout_cents >= 0);
  end if;
end;
$$;
comment on column public.player_company_hours.founder_payout_cents is
  'Automatic CEO payout of the hour (ADR-086): from the company cash to the founder; not part of profit_cents.';

-- ---------------------------------------------------------------------------
-- B. One operating hour as in M4c, then the CEO payout
-- ---------------------------------------------------------------------------

create or replace function public.player_company_close_hour(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours   double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_start   timestamptz := date_trunc('hour', p_hour_start);
  v_end     timestamptz;
  v_qid     bigint;
  v_team    jsonb;
  v_price   jsonb;
  v_stage   integer;
  v_demand  double precision;
  v_cap     double precision;
  v_sold    double precision;
  v_ctr     double precision;
  v_own     bigint;
  v_crev    bigint;
  v_hhbal   bigint;
  v_rev     bigint;
  v_cogs    bigint;
  v_gross   bigint;
  v_aidue   bigint;
  v_aipaid  bigint;
  v_pdue    bigint := 0;
  v_ppaid   bigint := 0;
  v_due     bigint;
  v_factor  integer;
  v_fixed   bigint;
  v_mk      bigint;
  v_costs   bigint;
  v_paid    bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_profit  bigint;
  v_owed    bigint;
  v_free    bigint;
  v_payout  bigint := 0;
  v_bps     integer;
  v_until   timestamptz;
  k         text;
  j         record;
begin
  if p_company is null or p_hour_start is null then
    return null;
  end if;
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_hours h where h.company_id = p_company and h.hour_start = v_start) then
    update public.player_companies set last_hour_at = greatest(last_hour_at, v_start + interval '1 hour')
     where company_id = p_company and last_hour_at < v_start + interval '1 hour';
    return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'skipped', 'already_closed');
  end if;
  v_end := v_start + interval '1 hour';
  select * into c from public.companies where id = p_company;
  select gq.id into v_qid from public.game_quarters gq where gq.starts_at <= v_start and gq.ends_at > v_start;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  k := 'pch:' || p_company::text || ':' || to_char(v_start at time zone 'UTC', 'YYYYMMDDHH24');

  -- sales of the hour with the quarter's awareness and quality; demand and capacity count in units at the
  -- normal price, the price strategy changes both price and demand (ADR-083)
  v_price := public.company_price_effect(pc.price_level, pc.quality);
  v_stage := least(greatest(coalesce((v_team ->> 'stage')::integer, 0), 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_demand := pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0 / v_hours
            * pc.awareness * (0.5 + 0.5 * pc.quality)
            * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random())
            * (v_price ->> 'demand')::double precision;
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000)
         * (1 + public.cfg_num(v_su, '{stages,capacityBonusPerStage}', 0.25) * v_stage)
         * public.company_capacity_factor(pc.expansion_level) / v_hours;
  v_sold := least(v_demand, v_cap);
  -- contract work: a share of the unused capacity at the normal price (ADR-083)
  v_ctr := case when pc.contract_work
                then greatest(0, v_cap - v_sold) * public.cfg_num(v_su, '{contractWork,shareOfFreeCapacity}', 0.25)
                else 0 end;
  v_own := round((v_sold * (v_price ->> 'price')::double precision)::numeric)::bigint;
  v_crev := round(v_ctr::numeric)::bigint;
  -- closed money system: the households pay at most what they have (own sales first)
  v_hhbal := greatest(0, coalesce((select a.balance_cents from public.ledger_accounts a where a.id = v_hh), 0));
  if v_own + v_crev > v_hhbal then
    v_own := least(v_own, v_hhbal);
    v_crev := least(v_crev, v_hhbal - v_own);
    v_sold := least(v_sold, v_own / greatest((v_price ->> 'price')::double precision, 0.0001));
    v_ctr := v_crev;
  end if;
  v_rev := v_own + v_crev;
  v_cogs := round((v_sold * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5)))::numeric)::bigint
          + round((v_ctr * (1 - public.cfg_num(v_su, '{contractWork,grossMargin}', 0.3)))::numeric)::bigint;
  v_gross := v_rev - v_cogs;

  -- wages due: AI workers and the hourly contract wages of the players (the founder draws no wage)
  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);
  for j in select pj.id, pj.salary_cents_per_hour, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    v_pdue := v_pdue + j.salary_cents_per_hour * public.job_payable_minutes(j.id, v_until) / 60;
  end loop;
  v_due := v_aidue + v_pdue;
  -- never more than the hour earned; everyone gets the same share (ADR-072)
  v_factor := case when v_due <= 0 then 10000 else least(10000, greatest(0, v_gross) * 10000 / v_due)::integer end;
  v_aipaid := v_aidue * v_factor / 10000;

  -- money: revenue (own sales and contract work) from the households, goods and AI wages back to them
  if v_rev > 0 then
    perform public.ledger_transfer(v_hh, v_acc, v_rev, 'company_revenue',
                                   'Umsatz ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':revenue', pc.founder_id);
  end if;
  if v_cogs + v_aipaid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_cogs + v_aipaid, 'company_costs', 'Wareneinsatz und KI-Kräfte',
                                   'company', p_company, k || ':goods', pc.founder_id);
  end if;
  -- players: the hour (up to the end of a notice) at contract wage x factor, with XP and branch minutes
  update public.player_companies set pay_factor_bps = v_factor where company_id = p_company;
  for j in select pj.id, pj.player_id, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    perform public.lock_player_accounts(j.player_id);
    v_ppaid := v_ppaid + public.accrue_job_salary(j.id, v_until);
  end loop;

  -- fixed costs (with the expansion level) and marketing from the cash; the rest becomes an open bill
  v_fixed := round((public.company_fixed_cost_cents(pc.tier, pc.expansion_level) / v_hours)::numeric)::bigint;
  v_mk := round((pc.marketing_cents_per_quarter / v_hours)::numeric)::bigint;
  v_costs := v_fixed + v_mk;
  select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_paid := least(v_costs, coalesce(v_cash, 0));
  if v_paid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_paid, 'company_costs', 'Fixkosten und Marketing',
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_paid;
  if v_unpaid = 0 and pc.unpaid_cents > 0 then
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, coalesce(v_cash, 0));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  v_profit := v_rev - v_cogs - v_ppaid - v_aipaid - v_fixed - v_mk;
  v_owed := pc.unpaid_cents + v_unpaid - v_settle;

  -- automatic CEO payout (ADR-086, founderPayoutCents): after the hour's own bookings, a share of a positive profit
  -- (rounded down) moves from the company cash to the founder's private cash like company_withdraw, never more than
  -- the free cash (cash minus open bills). A transfer, not a cost: profit_cents stays as computed above.
  v_bps := least(10000, greatest(0, coalesce(pc.founder_payout_bps, 0)));
  if v_profit > 0 and v_bps > 0 then
    select a.balance_cents - v_owed into v_free from public.ledger_accounts a where a.id = v_acc;
    v_payout := least(v_profit * v_bps / 10000, greatest(0, coalesce(v_free, 0)));
  end if;
  if v_payout > 0 then
    perform public.lock_player_accounts(pc.founder_id);
    perform public.ledger_transfer(v_acc, public.ledger_player_account(pc.founder_id, 'player_cash'), v_payout, 'transfer',
                                   'CEO-Auszahlung ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':payout', pc.founder_id);
    perform public.loan_withhold(pc.founder_id, v_payout, k || ':payout');
  end if;

  update public.player_companies
     set unpaid_cents = v_owed,
         distress = v_owed > 0,
         last_hour_at = greatest(pc.last_hour_at, v_end)
   where company_id = p_company;
  insert into public.player_company_hours (company_id, hour_start, game_quarter_id, demand_cents, capacity_cents, revenue_cents,
                                           contract_revenue_cents, cogs_cents, fixed_cents, marketing_cents, player_wages_due_cents,
                                           player_wages_paid_cents, ai_wages_due_cents, ai_wages_paid_cents, pay_factor_bps,
                                           paid_costs_cents, unpaid_added_cents, profit_cents, founder_payout_cents)
  values (p_company, v_start, v_qid, round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint, v_rev,
          v_crev, v_cogs, v_fixed, v_mk, v_pdue, v_ppaid, v_aidue, v_aipaid, v_factor, v_paid, v_unpaid, v_profit, v_payout);

  return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'quarter_id', v_qid, 'revenue_cents', v_rev,
                            'contract_revenue_cents', v_crev, 'profit_cents', v_profit, 'pay_factor_bps', v_factor,
                            'player_wages_paid_cents', v_ppaid, 'ai_wages_paid_cents', v_aipaid, 'unpaid_added_cents', v_unpaid,
                            'founder_payout_cents', v_payout);
end;
$$;
comment on function public.player_company_close_hour(uuid, timestamptz) is
  'Closes one operating hour of a player company (closeStartupHour, ADR-072/083) and pays '
  'the automatic CEO payout (ADR-086); idempotent per (company, hour).';

-- ---------------------------------------------------------------------------
-- C. COMPANY: payout share, payout of the last hour and of the day
-- ---------------------------------------------------------------------------
create or replace function public.company_live_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  v_day     timestamptz := ((public.game_now() at time zone 'Europe/Berlin')::date)::timestamp at time zone 'Europe/Berlin';
  v_qid     bigint := (public.current_game_quarter()).id;
  v_rev     bigint;
  v_profit  bigint;
  v_trev    bigint;
  v_tprofit bigint;
  v_qrev    bigint;
  v_qprofit bigint;
  v_tpay    bigint;
  h         public.player_company_hours;
begin
  select * into pc from public.player_companies where company_id = p_company;
  select * into h from public.player_company_hours x where x.company_id = p_company order by x.hour_start desc limit 1;
  v_rev := h.revenue_cents;
  v_profit := h.profit_cents;
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0), coalesce(sum(x.founder_payout_cents), 0)
    into v_trev, v_tprofit, v_tpay
    from public.player_company_hours x
   where x.company_id = p_company and x.hour_start >= v_day
     and x.hour_start < ((v_day at time zone 'Europe/Berlin') + interval '1 day') at time zone 'Europe/Berlin';
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0) into v_qrev, v_qprofit
    from public.player_company_hours x where x.company_id = p_company and x.game_quarter_id = v_qid;
  return jsonb_build_object(
    'last_hour_at', pc.last_hour_at,
    'revenue_per_hour_cents', coalesce(v_rev, 0),
    'profit_per_hour_cents', coalesce(v_profit, 0),
    'pay_factor_bps', pc.pay_factor_bps,
    'today_revenue_cents', v_trev,
    'today_profit_cents', v_tprofit,
    'quarter_revenue_cents', v_qrev,
    'quarter_profit_cents', v_qprofit,
    -- the last closed hour in detail (ADR-083: profit coach)
    'contract_revenue_per_hour_cents', coalesce(h.contract_revenue_cents, 0),
    'demand_per_hour_cents', coalesce(h.demand_cents, 0),
    'capacity_per_hour_cents', coalesce(h.capacity_cents, 0),
    'fixed_per_hour_cents', coalesce(h.fixed_cents, 0),
    'ai_wages_per_hour_cents', coalesce(h.ai_wages_paid_cents, 0),
    'marketing_per_hour_cents', coalesce(h.marketing_cents, 0),
    -- ADR-086: automatic CEO payout of the last closed hour and of the Berlin day
    'founder_payout_per_hour_cents', coalesce(h.founder_payout_cents, 0),
    'today_founder_payout_cents', v_tpay);
end;
$$;
comment on function public.company_live_json(uuid) is
  'COMPANY.live: last closed hour (with its details, ADR-083, and the CEO payout, ADR-086), Berlin day and running quarter of a player company (ADR-072).';

create or replace function public.company_hours_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('hour_start', x.hour_start, 'revenue_cents', x.revenue_cents,
                                               'contract_revenue_cents', x.contract_revenue_cents,
                                               'profit_cents', x.profit_cents,
                                               'founder_payout_cents', x.founder_payout_cents) order by x.hour_start), '[]'::jsonb)
    from (select h.hour_start, h.revenue_cents, h.contract_revenue_cents, h.profit_cents, h.founder_payout_cents from public.player_company_hours h
           where h.company_id = p_company order by h.hour_start desc limit 24) x;
$$;
comment on function public.company_hours_json(uuid) is 'COMPANY.hours: the last 24 closed operating hours, oldest first.';

-- company_state as in M4c plus the CEO payout share (ADR-086)
create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
  v_mf     double precision;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps,
           'bonus_cents', r.bonus_cents)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  v_cost := public.company_upgrade_cost(pc.tier);
  -- the estimate describes the market the company reaches (ADR-083)
  v_mf := public.company_market_factor(pc.tier, pc.expansion_level);
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'logo', public.company_logo(p_company),
    'logo_hidden', pc.logo_hidden,
    'founder_has_job', exists (select 1 from public.player_jobs x where x.player_id = pc.founder_id and x.status = 'active'),
    'full_time_from', public.config_double('startups', '{fullTimeFromEmployees}', 5)::integer,
    'training_from', public.config_double('startups', '{training,fromEmployees}', 5)::integer,
    'headcount', public.company_headcount(p_company),
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'distress_quarters', pc.distress_quarters,
    'grace_quarters', public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer,
    'pay_factor_bps', pc.pay_factor_bps,
    'product_key', public.company_product(p_company) ->> 'key',
    'stage', (v_team ->> 'stage')::integer,
    'stages', public.company_stages_json(p_company),
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents * v_mf
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents * v_mf
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 72000),
    'ai_wage_cents_per_hour', public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000),
    'ai_worker_skills', to_jsonb(pc.ai_worker_skills),
    'max_employees', public.company_max_employees(p_company),
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', round((v_team ->> 'capacity_cents')::bigint * public.company_capacity_factor(pc.expansion_level))::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', public.company_next_tier(pc.tier) is not null
                   and coalesce(v_level, 1) >= (public.company_tier_cfg(public.company_next_tier(pc.tier)) ->> 'minLevel')::integer,
    'listing', public.company_listing_json(p_company, pc.founder_id),
    'can_go_public', c.phase = 'private' and public.company_open_offer(p_company) is null
                     and coalesce(public.config_jsonb('startups', '{ipo,fromTiers}'), '["garage", "small_business", "gmbh"]'::jsonb) ? pc.tier
                     and coalesce(v_level, 1) >= public.config_double('startups', '{ipo,minLevel}', 6),
    'can_capital_increase', c.phase = 'listed' and public.company_open_offer(p_company) is null,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist,
    'live', public.company_live_json(p_company),
    'hours', public.company_hours_json(p_company))
    || jsonb_build_object(
         'banner', pc.banner,
         -- ADR-083: price strategy, contract work, expansion
         'price_level', pc.price_level,
         'contract_work', pc.contract_work,
         'expansion_level', pc.expansion_level,
         'can_expand', public.company_can_expand(pc.tier),
         'expansion_cost_cents', case when public.company_can_expand(pc.tier)
                                      then public.company_expansion_cost_cents(pc.expansion_level) end,
         'market_factor', round(v_mf::numeric, 4),
         -- ADR-086: share of the hourly profit paid to the founder automatically
         'founder_payout_bps', pc.founder_payout_bps);
end;
$$;

-- ---------------------------------------------------------------------------
-- D. RPC: payout share (founder only)
-- ---------------------------------------------------------------------------
create or replace function public.set_founder_payout(p_request_id uuid, p_bps integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  v_step    integer := greatest(1, public.config_double('startups', '{founderPayout,stepBps}', 500)::integer);
  v_max     integer := least(10000, public.config_double('startups', '{founderPayout,maxBps}', 10000)::integer);
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_bps is null or p_bps < 0 or p_bps > v_max or p_bps % v_step <> 0 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_founder_payout');
  if v_replay is not null then
    return v_replay;
  end if;
  update public.player_companies set founder_payout_bps = p_bps where company_id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.set_founder_payout(uuid, integer) is
  'RPC (founder): share of the hourly profit paid out automatically, whole steps of startups.founderPayout (ADR-086); '
  'errors company_not_found, invalid_argument.';

-- ---------------------------------------------------------------------------
-- E. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.player_company_close_hour(uuid, timestamptz)', 'public.company_live_json(uuid)', 'public.company_hours_json(uuid)',
    'public.company_state(uuid)', 'public.set_founder_payout(uuid, integer)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  grant execute on function public.set_founder_payout(uuid, integer) to authenticated;
end;
$$;

commit;
